<template><AdministrationLayout search-placeholder="Rechercher une catégorie…" v-slot="{ search }"><section class="page-card"><header class="title"><div class="title-icon">◆</div><div><h1>Gestion des catégories de pannes</h1><p>Organisez les types de prestations proposées sur ReparSystem.</p></div><button @click="openCreate">＋ Nouvelle Catégorie</button></header><div class="filters"><label>⌕ <input v-model="localSearch" placeholder="Rechercher une catégorie…"></label><select v-model="status"><option value="all">Toutes les catégories</option><option value="active">Actives</option><option value="inactive">Inactives</option></select></div><TableauCategories :categories="filtered(search)" @edit="openEdit" @delete="confirmDelete"/><footer class="summary">Affichage de 1 à {{ filtered(search).length }} sur {{ categories.length }} catégories</footer></section><AjouterCategorieModal v-if="modalOpen" :category="selected" @close="modalOpen=false" @save="save"/></AdministrationLayout></template>
<script setup>import { onMounted, ref } from 'vue';import AdministrationLayout from '../../components/administrateur/AdministrationLayout.vue';import TableauCategories from '../../components/administrateur/TableauCategories.vue';import AjouterCategorieModal from '../../modales/administrateur/AjouterCategorieModal.vue';import { useCategories } from '../../services/serviceCategories';const {categories,charger,create,update,remove}=useCategories();const localSearch=ref('');const status=ref('all');const modalOpen=ref(false);const selected=ref(null);const filtered=(headerSearch)=>categories.value.filter(c=>{const terms=`${localSearch.value} ${headerSearch}`.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);const content=`${c.name} ${c.description}`.toLocaleLowerCase();return terms.every(term=>content.includes(term))&&(status.value==='all'||(status.value==='active')===c.active)});function openCreate(){selected.value=null;modalOpen.value=true}function openEdit(category){selected.value=category;modalOpen.value=true}async function save(data){await (selected.value?update({...selected.value,...data}):create(data));modalOpen.value=false}async function confirmDelete(category){if(window.confirm(`Supprimer la catégorie « ${category.name} » ?`))await remove(category.id)}onMounted(charger)</script>
<style scoped>.page-card{background:#fff;border:1px solid #e2eefb;border-radius:11px;padding:16px;box-shadow:0 4px 20px #114d9710}.title{display:flex;align-items:center;gap:14px;padding:0 0 20px;border-bottom:1px solid #e4effb}.title-icon{display:grid;place-items:center;width:58px;height:58px;border-radius:13px;background:#e5f4f0;color:#087f70;font-size:28px}.title h1{text-transform:uppercase;font-size:20px;margin:0;color:#174b50}.title p{color:#5475ad;margin:7px 0 0}.title button{margin-left:auto;background:#087f70;color:#fff;padding:14px 18px;border-radius:9px;font-size:13px}.filters{display:flex;gap:14px;padding:14px 0}.filters label{height:44px;flex:1;display:flex;align-items:center;gap:11px;padding:0 13px;border:1px solid #bcd9ff;border-radius:8px;color:#087f70;font-size:22px}.filters input{width:100%;border:0;outline:0;font:inherit;font-size:13px}.filters select{width:260px;border:1px solid #d2e2f6;border-radius:8px;padding:0 12px;background:#f9fcff;color:#24518e;font:inherit;font-size:13px}.summary{padding:18px 5px 3px;color:#6381b5;font-size:13px}@media(max-width:680px){.title{align-items:flex-start;flex-wrap:wrap}.title h1{font-size:16px}.title button{margin-left:72px;margin-top:-8px}.filters{flex-direction:column}.filters select{width:100%}}</style>
